      if (row.status !== "trashed") throw new DomainError("product_not_trashed", 409, "Only products in the recycle bin can be permanently deleted");
      if (Number(row.revision) !== data.expectedRevision) throw new DomainError("product_revision_conflict", 409, "Product has changed since it was loaded");
