async function runOperationalRetentionCleanup(input) {
  const maxRows = input.maxRows ?? DEFAULT_MAX_ROWS;
  const deadline = performance.now() + (input.maxDurationMs ?? DEFAULT_MAX_DURATION_MS);
  const cutoff = input.now - input.retentionMs;
  let commerceRows = 0;
  for (const table2 of [
    {
      name: "notification_deliveries",
      predicate: "status IN ('delivered', 'failed') AND updated_at < ?"
    },
    {
      name: "outbox_events",
      predicate: "status IN ('published', 'failed') AND updated_at < ?"
    },
    {
      name: "operation_task_runs",
      predicate: "status IN ('succeeded', 'failed') AND completed_at < ? AND (artifact_object_key IS NULL OR artifact_deleted_at IS NOT NULL)"
    }
  ]) {
    if (commerceRows >= maxRows || performance.now() >= deadline) break;
    commerceRows += await deleteTerminalRows(input.db, table2.name, table2.predicate, cutoff, Math.min(CLEANUP_BATCH_SIZE, maxRows - commerceRows));
  }
  const auditExports = await deleteExpiredAuditExports(input.db, input.bucket, input.now, Math.min(AUDIT_EXPORT_BATCH_SIZE, Math.max(0, maxRows - commerceRows)));
  return {
    affectedRows: commerceRows + auditExports,
    commerceRows,
    auditExports
  };
}
async function deleteTerminalRows(db, table2, predicate, cutoff, limit) {
  if (limit === 0) return 0;
  const timestamp = table2 === "operation_task_runs" ? "completed_at" : "updated_at";
  const result = await db.prepare(`DELETE FROM ${table2} WHERE id IN (
			 SELECT id FROM ${table2} WHERE ${predicate}
			 ORDER BY ${timestamp}, id LIMIT ?
			)`).bind(cutoff, limit).run();
  return Number(result.meta.changes ?? 0);
}
async function deleteExpiredAuditExports(db, bucket, now3, limit) {
  if (limit === 0) return 0;
  const due = await db.prepare(`SELECT id, artifact_object_key FROM operation_task_runs
			 INDEXED BY operation_task_runs_artifact_retention_idx
			 WHERE delete_after <= ? AND artifact_object_key IS NOT NULL
			 AND artifact_deleted_at IS NULL
			 ORDER BY delete_after, id LIMIT ?`).bind(now3, limit).all();
  if (!due.results.length) return 0;
  await bucket.delete(due.results.map((row) => row.artifact_object_key));
  return (await db.batch(due.results.map((row) => db.prepare(`UPDATE operation_task_runs SET artifact_deleted_at = ?
					 WHERE id = ? AND artifact_deleted_at IS NULL`).bind(now3, row.id)))).reduce((sum2, result) => sum2 + Number(result.meta.changes ?? 0), 0);
}
